func TestShipwreckWaterloggingAndChunkClipping(t *testing.T) {
	r := newDecorRegion(newGoldenTerrain(), newChunk(0, 0), worldMinY, worldHeight)
	r.bindProtos(ChunkPos{})
	slab := registry.BlockOakSlab.DefaultState()
	wet, _ := registry.WithBool(slab, registry.PropWaterlogged, true)
	water := registry.BlockWater.DefaultState()
	template := &Template{Size: [3]int32{8, 1, 1}, Palettes: [][]TemplateBlock{{
		{Pos: [3]int32{0, 0, 0}, State: slab},
		{Pos: [3]int32{1, 0, 0}, State: water},
		{Pos: [3]int32{2, 0, 0}, State: slab},
		{Pos: [3]int32{3, 0, 0}, State: wet},
		{Pos: [3]int32{4, 0, 0}, State: airState},
		{Pos: [3]int32{5, 0, 0}, State: slab},
		{Pos: [3]int32{6, 0, 0}, State: slab},
		{Pos: [3]int32{7, 0, 0}, State: registry.BlockOakPlanks.DefaultState()},
	}}}
	r.set(4, 100, 0, registry.BlockStone.DefaultState())
	r.set(5, 100, 1, water)
	p := &shipwreckPiece{template: template, pos: [3]int32{0, 100, 0}, adjusted: true}
	p.box = p.templateBox()
	p.place(r, jbox{0, worldMinY, 0, 6, 319, 15}, [3]int32{})
	for _, x := range []int32{0, 2} {
		if registry.StateBool(r.get(x, 100, 0), registry.PropWaterlogged) {
			t.Fatalf("template source leaked to %d", x)
		}
	}
	for _, x := range []int32{3, 5, 6} {
		if !registry.StateBool(r.get(x, 100, 0), registry.PropWaterlogged) {
			t.Fatalf("missing waterlogging at %d", x)
		}
	}
	if registry.BlockOf(r.get(4, 100, 0)) != registry.BlockStone {
		t.Fatal("template air replaced terrain")
	}
	if !r.src.isAir(r.get(7, 100, 0)) {
		t.Fatal("placement escaped writable chunk")
	}
}

func TestShipwreckLeavesDoubleSlabDryInWater(t *testing.T) {
	r := newDecorRegion(newGoldenTerrain(), newChunk(0, 0), worldMinY, worldHeight)
	r.bindProtos(ChunkPos{})
	double, _ := registry.WithBool(registry.BlockOakSlab.DefaultState(), registry.PropWaterlogged, false)
	double, _ = registry.WithProps(double, registry.PropValue{P: registry.PropType, V: "double"})
	water := registry.BlockWater.DefaultState()
	template := &Template{Size: [3]int32{2, 1, 1}, Palettes: [][]TemplateBlock{{
		{Pos: [3]int32{0, 0, 0}, State: double},
		{Pos: [3]int32{1, 0, 0}, State: double},
	}}}
	r.set(0, 100, 0, water)
	r.set(1, 100, 1, water)
	p := &shipwreckPiece{template: template, pos: [3]int32{0, 100, 0}, adjusted: true}
	p.box = p.templateBox()
	p.place(r, jbox{0, worldMinY, 0, 15, 319, 15}, [3]int32{})
	for _, x := range []int32{0, 1} {
		if registry.StateBool(r.get(x, 100, 0), registry.PropWaterlogged) {
			t.Errorf("double slab at x=%d waterlogged", x)
		}
	}
}

